    mut quantize: *mut aptx_quantize,
    mut sample_difference: int32_t,
    mut dither: int32_t,
    mut quantization_factor: int32_t,
    mut tables: *const aptx_tables,
) {
    let quantize_view: &mut aptx_quantize = unsafe { &mut *quantize };
    let tables_ref: &aptx_tables = unsafe { &*tables };
    let intervals_ptr: *const int32_t = tables_ref.quantize_intervals;
    let quantize_dither_factors_ptr: *const int32_t = tables_ref.quantize_dither_factors;
    let tables_size: c_int = tables_ref.tables_size;
    let mut quantized_sample: int32_t = 0;
    let mut dithered_sample: int32_t = 0;
    let mut parity_change: int32_t = 0;
    let mut d: int32_t = 0;
    let mut mean: int32_t = 0;
    let mut interval: int32_t = 0;
    let mut inv: int32_t = 0;
    let mut sample_difference_abs: int32_t = 0;
    let mut error: int64_t = 0;

    sample_difference_abs = sample_difference;
    if sample_difference_abs < 0 as int32_t {
        sample_difference_abs = -sample_difference_abs;
    }
    if sample_difference_abs > ((1 as c_int as int32_t) << 23 as c_int) - 1 as int32_t {
        sample_difference_abs = ((1 as c_int as int32_t) << 23 as c_int) - 1 as int32_t;
    }

    quantized_sample = aptx_bin_search(
        sample_difference_abs >> 4 as c_int,
        quantization_factor,
        intervals_ptr,
        tables_size,
    );

    let quantized_sample_usize = quantized_sample as usize;
    let tables_size_usize = tables_size as usize;
    // SAFETY: `quantize_dither_factors_ptr` comes from `tables_ref`; caller provides valid
    // table storage with `tables_size` elements, non-null for this access pattern, and this
    // function creates only an immutable view, so no mutable alias is introduced.
