        unsafe { core::slice::from_raw_parts(quantize_dither_factors_ptr, tables_size_usize) };
    // SAFETY: `intervals_ptr` comes from `tables_ref`; caller provides valid interval table
    // storage with at least `tables_size + 1` elements because this function reads entries
    // at `quantized_sample` and `quantized_sample + 1`, the pointer is non-null for these
    // accesses, and this is an immutable view only.
    let intervals = unsafe { core::slice::from_raw_parts(intervals_ptr, tables_size_usize + 1) };

    d = rshift32_clip24(
        (dither as int64_t * dither as int64_t >> 32 as c_int) as int32_t,
        7 as c_uint,
    ) - ((1 as c_int as int32_t) << 23 as c_int);
    d = rshift64(
        d as int64_t
            * unsafe { *quantize_dither_factors.get_unchecked(quantized_sample_usize) } as int64_t,
        23 as c_uint,
    ) as int32_t;

    let interval_pair = unsafe {
        // SAFETY: `aptx_bin_search(..., tables_size)` returns an index in `0..tables_size`;
        // the interval access pattern requires elements at `quantized_sample` and
